import json,re,urllib.request,urllib.error,urllib.parse,http.client
def reconcile_submit(base,request_id,digest):
    parsed=urllib.parse.urlsplit(base)
    if parsed.scheme!='http' or parsed.hostname!='127.0.0.1' or parsed.path not in ('','/') or parsed.query or parsed.fragment:raise ValueError('private API endpoint')
    if not isinstance(request_id,str) or not re.fullmatch(r'[a-z0-9_-]{1,40}',request_id) or not isinstance(digest,str) or not re.fullmatch(r'[0-9a-f]{64}',digest):raise ValueError('operation identity')
    base=base.rstrip('/')
    def lookup(identity):
        try:
            with urllib.request.urlopen(base+'/operations/'+urllib.parse.quote(identity,safe=''),timeout=.5) as response:return json.loads(response.read())
        except urllib.error.HTTPError as error:
            code=error.code;error.close()
            if code==404:return {'id':request_id,'digest':digest,'status':'unknown'}
            raise
    request=urllib.request.Request(base+'/operations',data=json.dumps({'id':request_id,'digest':digest}).encode(),headers={'Content-Type':'application/json'},method='POST')
    try:
        with urllib.request.urlopen(request,timeout=.5) as response:result=json.loads(response.read())
    except urllib.error.HTTPError as error:
        code=error.code;error.close()
        if code==409:raise ValueError('operation identity conflict') from error
        raise
    except (OSError,http.client.HTTPException):
        result=lookup(request_id)
    if not isinstance(result,dict) or result.get('id')!=request_id or result.get('digest')!=digest or result.get('status') not in ('queued','running','succeeded','failed','unknown'):raise ValueError('mismatched authoritative operation')
    return result
